---
import { ClientRouter } from 'astro:transitions';
import { DATABUDDY_WEBSITE_ID } from "../lib/databuddy";

// Import the global.css file here so that it is included on
// all pages through the use of the <BaseHead /> component.

interface Props {
  title: string;
  description: string;
  image?: string;
  type?: "website" | "article";
}

const canonicalURL = new URL(Astro.url.pathname, Astro.site);
// Every page has a Markdown twin (astro.config.mjs writes it; worker.ts serves it for Accept: text/markdown).
const markdownURL = new URL(`${Astro.url.pathname.replace(/\/$/, "") || "/index"}.md`, Astro.site);

// Each platform crops to a different ratio, so each gets its own image.
const { title, description, image = "/og/og-linkedin.png", type = "website" } = Astro.props;
const twitterImage = Astro.props.image ?? "/og/og-twitter.png";

// X, LinkedIn and Discord cache card images by URL. Bump this when the OG images change so they fetch the new ones.
const OG_VERSION = "2";
const ogImageUrl = (path: string) => {
  const url = new URL(path, Astro.url);
  url.searchParams.set("v", OG_VERSION);
  return url;
};
---

<!-- Global Metadata -->
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />

<link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png" />
<link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png" />
<link rel="icon" type="image/png" sizes="16x16" href="/favicon-16x16.png" />
<link rel="icon" type="image/x-icon" href="/favicon.ico" />
<link rel="manifest" href="/site.webmanifest" />

<meta name="generator" content={Astro.generator} />

<!-- Font preloads -->
<link
  rel="preload"
  href="/fonts/recoleta.woff2"
  as="font"
  type="font/woff2"
  crossorigin
/>

<!-- Canonical URL -->
<link rel="canonical" href={canonicalURL} />

<!-- Primary Meta Tags -->
<title>{title}</title>
<meta name="title" content={title} />
<meta name="description" content={description} />
<meta name="author" content="Sara Natour" />
<meta name="keywords" content="Sara Natour, Software Developer, Web Development, Full-stack Development, Testing, Convex, Astro, React, AI Agents, Electronics Design" />

<!-- Open Graph / Facebook -->
<meta property="og:type" content={type} />
<meta property="og:url" content={Astro.url} />
<meta property="og:title" content={title} />
<meta property="og:description" content={description} />
<meta property="og:image" content={ogImageUrl(image)} />
<meta property="og:image:alt" content={title} />
<meta property="og:site_name" content="Sara Natour" />
<meta property="og:locale" content="en_US" />
<meta name="theme-color" content="#fcf8ef" />
<!-- Twitter -->
<meta property="twitter:card" content="summary_large_image" />
<meta property="twitter:url" content={Astro.url} />
<meta property="twitter:title" content={title} />
<meta property="twitter:description" content={description} />
<meta property="twitter:image" content={ogImageUrl(twitterImage)} />
<!-- Databuddy analytics (cookieless, no PII) -->
<script
  src="https://cdn.databuddy.cc/databuddy.js"
  is:inline
  data-client-id={DATABUDDY_WEBSITE_ID}
  async
  crossorigin="anonymous"
  ></script>
<!-- Fonts link -->

<!-- Sitemap link -->
<link rel="sitemap" href="/sitemap-index.xml" />
<link rel="alternate" type="application/rss+xml" title="Sara Natour" href="/rss.xml" />
<link rel="alternate" type="text/markdown" href={markdownURL} />
<ClientRouter />
/*
  Vary: Accept

/
  Link: </.well-known/api-catalog>; rel="api-catalog"
  Link: </openapi.json>; rel="service-desc"
  Link: </llms.txt>; rel="service-doc"
  Link: </index.md>; rel="alternate"; type="text/markdown"

/.well-known/api-catalog
  Content-Type: application/linkset+json; profile="https://www.rfc-editor.org/info/rfc9727"
import { trackAgents } from "@databuddy/sdk/agents";
import { prefersMarkdown } from "./src/lib/accept";
import { DATABUDDY_WEBSITE_ID } from "./src/lib/databuddy";

// ponytail: inline types instead of adding @cloudflare/workers-types for one file
interface Env {
	ASSETS: { fetch(request: Request): Promise<Response> };
}

export default {
	async fetch(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
		ctx.waitUntil(trackAgents(request, { websiteId: DATABUDDY_WEBSITE_ID }));
		if (["GET", "HEAD"].includes(request.method) && prefersMarkdown(request.headers.get("accept") ?? "")) {
			const url = new URL(request.url);
			const path = url.pathname.replace(/\/$/, "") || "/index";
			const asset = await env.ASSETS.fetch(new Request(new URL(`${path}.md`, url)));
			// No .md twin (images, llms.txt, 404s): fall through to the normal response.
			if (asset.ok) {
				const markdown = await asset.text();
				const headers = new Headers(asset.headers);
				headers.set("Content-Type", "text/markdown; charset=utf-8");
				headers.set("Vary", "Accept");
				// ponytail: ~4 chars per token estimate, a real tokenizer isn't worth the bundle size
				headers.set("x-markdown-tokens", String(Math.ceil(markdown.length / 4)));
				// Same policy as robots.txt.
				headers.set("Content-Signal", "ai-train=no, search=yes, ai-input=yes");
				return new Response(markdown, { headers });
			}
		}
		// Assets-only site: no origin to fetch(request) from, serve dist/ instead.
		return env.ASSETS.fetch(request);
	},
};
{
	"name": "site",
	"compatibility_date": "2026-06-12",
	"main": "./worker.ts",
	"assets": {
		"directory": "./dist",
		"binding": "ASSETS",
		// Without this, static hits skip the worker and never get tracked.
		"run_worker_first": true
	},
	// Required by `wrangler preview` (PR preview deploys). Empty: previews use the same settings as production.
	"previews": {},
	"observability": {
		"enabled": false,
		"head_sampling_rate": 1,
		"redact_query_string": false,
		"logs": {
			"enabled": true,
			"head_sampling_rate": 1,
			"invocation_logs": true,
			"persist": true
		},
		"traces": {
			"enabled": true,
			"head_sampling_rate": 1,
			"persist": true
		},
		// The dashboard calls this "issue_detection"; wrangler's key is "issues".
		"issues": {
			"enabled": true
		}
	}
}
