   353	    if (!audio || !article || !track || !CSS.highlights) return; // player only, no highlighting
   354	
   355	    // One Range per sentence, in page order.
   356	    // ponytail: a list item with a nested list yields its nested sentences twice;
   357	    // skip blocks containing a nested li if articles start using nested lists.
   358	    const segmenter = new Intl.Segmenter("en", { granularity: "sentence" });
   359	    const sentences: { key: string; range: Range }[] = [];
   360	    for (const block of article.querySelectorAll("p, h2, h3, h4, li")) {
   361	      if (block.closest("pre") || block.querySelector("p")) continue;
   362	      const walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT);
   363	      const nodes: Text[] = [];
   364	      while (walker.nextNode()) nodes.push(walker.currentNode as Text);
   365	      const at = (offset: number): [Text, number] => {
   366	        for (const node of nodes) {
   367	          if (offset <= node.length) return [node, offset];
   368	          offset -= node.length;
   369	        }
   370	        return [nodes[nodes.length - 1], nodes[nodes.length - 1].length];
