   239	  /* Thin scrubber: filled up to the playhead (--fill, set by the script), round blue thumb. */
   240	  [data-seek] {
   241	    appearance: none;
   242	    height: 4px;
   243	    background: linear-gradient(to right, var(--color-blue-1) var(--fill, 0%), color-mix(in srgb, var(--color-black-1) 12%, transparent) 0);
   244	    border-radius: 999px;
   245	  }
   246	  [data-seek]::-webkit-slider-thumb {
   247	    appearance: none;
   248	    width: 12px;
   249	    height: 12px;
   250	    border-radius: 50%;
   251	    background: var(--color-blue-1);
   252	  }
   253	  [data-seek]::-moz-range-thumb {
   254	    width: 12px;
   255	    height: 12px;
   256	    border: 0;
   257	    border-radius: 50%;
   258	    background: var(--color-blue-1);
   259	  }
   260	</style>
   261	
   262	<script>
   263	  // Follows the narration: each cue in the .vtt is one sentence; the matching
   264	  // sentence on the page is highlighted (CSS Custom Highlight API, no markup added).
   265	  const norm = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");
   266	
   267	  document.addEventListener("astro:page-load", () => {
   268	    CSS.highlights?.delete("narration");
   269	    const audio = document.querySelector<HTMLAudioElement>("audio[data-narration]");
   270	    const article = document.querySelector("article[data-article]");
   271	    const track = audio?.textTracks[0];
   272	
   273	    // Custom player, driving the same <audio> element.
   274	    const player = document.querySelector<HTMLElement>("[data-player]");
   275	    if (audio && player) {
   276	      const q = <T extends Element>(sel: string) => player.querySelector<T>(sel)!;
   277	      const play = q<HTMLButtonElement>("[data-play]");
   278	      const mute = q<HTMLButtonElement>("[data-mute]");
   279	      const seek = q<HTMLInputElement>("[data-seek]");
   280	      const time = q<HTMLElement>("[data-time]");
   281	      const rate = q<HTMLElement>("[data-rate]");
   282	      const speeds = [0.75, 1, 1.25, 1.5, 1.75, 2];
   283	      const clock = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
   284	      const sync = () => {
   285	        const total = Number.isFinite(audio.duration) ? audio.duration : 0;
   286	        seek.max = String(total);
   287	        seek.value = String(audio.currentTime);
   288	        seek.style.setProperty("--fill", `${total ? (audio.currentTime / total) * 100 : 0}%`);
   289	        time.textContent = total ? `${clock(audio.currentTime)} / ${clock(total)}` : clock(audio.currentTime);
   290	        q("[data-icon-play]").classList.toggle("hidden", !audio.paused);
   291	        q("[data-icon-pause]").classList.toggle("hidden", audio.paused);
   292	        play.setAttribute("aria-label", audio.paused ? "Play narration" : "Pause narration");
   293	        q("[data-icon-sound]").classList.toggle("hidden", audio.muted);
   294	        q("[data-icon-muted]").classList.toggle("hidden", !audio.muted);
   295	        mute.setAttribute("aria-label", audio.muted ? "Unmute" : "Mute");
   296	        rate.textContent = `${audio.playbackRate}x`;
   297	      };
   298	      // Collapsed to a "Listen" button until asked for; closing pauses and collapses again.
   299	      const listen = document.querySelector<HTMLButtonElement>("[data-listen]")!;
   300	      const open = (show: boolean) => {
   301	        player.hidden = !show;
   302	        listen.hidden = show;
   303	      };
   304	      audio.controls = false;
   305	      audio.hidden = true;
   306	      open(false);
   307	      listen.addEventListener("click", () => {
   308	        open(true);
   309	        audio.play();
   310	        play.focus();
   311	      });
   312	      q("[data-close]").addEventListener("click", () => {
   313	        audio.pause();
   314	        open(false);
   315	        listen.focus();
   316	      });
   317	      for (const event of ["loadedmetadata", "timeupdate", "play", "pause", "ended", "volumechange", "ratechange"]) {
   318	        audio.addEventListener(event, sync);
   319	      }
   320	      play.addEventListener("click", () => (audio.paused ? audio.play() : audio.pause()));
   321	      mute.addEventListener("click", () => (audio.muted = !audio.muted));
   322	      seek.addEventListener("input", () => (audio.currentTime = Number(seek.value)));
   323	      for (const button of player.querySelectorAll<HTMLButtonElement>("[data-skip]")) {
   324	        button.addEventListener("click", () => {
   325	          audio.currentTime = Math.min(Math.max(audio.currentTime + Number(button.dataset.skip), 0), audio.duration || 0);
   326	        });
   327	      }
   328	      for (const button of player.querySelectorAll<HTMLButtonElement>("[data-speed]")) {
   329	        button.addEventListener("click", () => {
   330	          const i = speeds.indexOf(audio.playbackRate);
   331	          const next = speeds[Math.min(Math.max((i < 0 ? 1 : i) + Number(button.dataset.speed), 0), speeds.length - 1)];
   332	          audio.playbackRate = next;
   333	          audio.defaultPlaybackRate = next; // survives a Krisp / Original switch
   334	        });
   335	      }
   336	      // Krisp / Original: swap the file, keep the position and play state.
   337	      const versions = player.querySelectorAll<HTMLButtonElement>("[data-version]");
   338	      for (const button of versions) {
   339	        button.addEventListener("click", () => {
   340	          if (button.getAttribute("aria-checked") === "true") return;
   341	          for (const other of versions) other.setAttribute("aria-checked", String(other === button));
   342	          const { currentTime, paused } = audio;
   343	          audio.src = button.dataset.version!;
   344	          audio.addEventListener("loadedmetadata", () => {
   345	            audio.currentTime = currentTime;
   346	            if (!paused) audio.play();
   347	          }, { once: true });
   348	        });
   349	      }
   350	      sync();
   351	    }
   352	
   353	    if (!audio || !article || !track || !CSS.highlights) return; // player only, no highlighting
   354	
   355	    // One Range per sentence, in page order.
   356	    // ponytail: a list item with a nested list yields its nested sentences twice;
   357	    // skip blocks containing a nested li if articles start using nested lists.
   358	    const segmenter = new Intl.Segmenter("en", { granularity: "sentence" });
   359	    const sentences: { key: string; range: Range }[] = [];
   360	    for (const block of article.querySelectorAll("p, h2, h3, h4, li")) {
   361	      if (block.closest("pre") || block.querySelector("p")) continue;
   362	      const walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT);
   363	      const nodes: Text[] = [];
   364	      while (walker.nextNode()) nodes.push(walker.currentNode as Text);
   365	      const at = (offset: number): [Text, number] => {
   366	        for (const node of nodes) {
   367	          if (offset <= node.length) return [node, offset];
   368	          offset -= node.length;
   369	        }
   370	        return [nodes[nodes.length - 1], nodes[nodes.length - 1].length];
   371	      };
   372	      for (const { segment, index } of segmenter.segment(block.textContent ?? "")) {
   373	        const key = norm(segment);
   374	        if (!key) continue;
   375	        const range = new Range();
   376	        range.setStart(...at(index));
   377	        range.setEnd(...at(index + segment.trimEnd().length));
   378	        sentences.push({ key, range });
   379	      }
   380	    }
   381	
   382	    // Cues are matched to sentences by text, in order, so editing the article
   383	    // after recording only un-highlights the edited sentence.
   384	    let byCue: Map<TextTrackCue, Range> | undefined;
   385	    const matchCues = () => {
   386	      byCue = new Map();
   387	      let from = 0;
   388	      for (const cue of track.cues ?? []) {
   389	        const key = norm((cue as VTTCue).getCueAsHTML().textContent ?? "");
   390	        const i = sentences.findIndex((s, i) => i >= from && s.key === key);
   391	        if (i < 0) continue;
   392	        byCue.set(cue, sentences[i].range);
   393	        from = i + 1;
   394	      }
   395	    };
   396	
   397	    const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
   398	    track.mode = "hidden"; // load cues and fire cuechange without rendering them
   399	    track.addEventListener("cuechange", () => {
   400	      if (!byCue) matchCues();
   401	      const cue = track.activeCues?.[0];
   402	      const range = cue && byCue!.get(cue);
   403	      if (!range) return;
   404	      CSS.highlights.set("narration", new Highlight(range));
   405	      if (!audio.paused) {
   406	        range.startContainer.parentElement?.scrollIntoView({
   407	          block: "center",
   408	          behavior: reducedMotion.matches ? "auto" : "smooth",
   409	        });
   410	      }
   411	    });
   412	
   413	    // Dev only: play the recording and press Space as each sentence starts.
   414	    // Saving downloads <slug>.vtt, which goes in public/narration/.
   415	    const tapButton = import.meta.env.DEV ? document.querySelector<HTMLButtonElement>("button[data-tap]") : null;
   416	    if (tapButton) {
   417	      const TAP_LAG = 0.2; // seconds a tap trails the voice; tune if highlights feel late or early
   418	      const starts: number[] = [];
   419	      let tapping = false;
   420	      const stamp = (t: number) => new Date(Math.max(t, 0) * 1000).toISOString().slice(11, 23);
   421	      const show = () => {
   422	        const current = sentences[starts.length - 1];
   423	        if (current) {
   424	          CSS.highlights.set("narration", new Highlight(current.range));
   425	          current.range.startContainer.parentElement?.scrollIntoView({ block: "center" });
   426	        } else CSS.highlights.delete("narration");
   427	        tapButton.textContent = `${starts.length}/${sentences.length} sentences marked. Space: next sentence starts now. Backspace: undo. Click here to save.`;
   428	      };
   429	      tapButton.addEventListener("click", () => {
   430	        tapButton.blur(); // so Space doesn't re-click the button
   431	        if (!tapping) {
   432	          tapping = true;
   433	          track.mode = "disabled"; // old timings must not fight the taps
   434	          starts.length = 0;
   435	          audio.currentTime = 0;
   436	          audio.play();
   437	          show();
   438	          return;
   439	        }
   440	        tapping = false;
   441	        audio.pause();
   442	        const cues = starts.map((start, i) => {
   443	          const text = sentences[i].range.toString().replace(/\s+/g, " ").trim().replace(/&/g, "&amp;").replace(/</g, "&lt;");
   444	          return `${stamp(start - TAP_LAG)} --> ${stamp((starts[i + 1] ?? audio.duration + TAP_LAG) - TAP_LAG)}\n${text}\n`;
   445	        });
   446	        const link = document.createElement("a");
   447	        link.href = URL.createObjectURL(new Blob([`WEBVTT\n\n${cues.join("\n")}`], { type: "text/vtt" }));
   448	        link.download = `${tapButton.dataset.slug}.vtt`;
   449	        link.click();
   450	        tapButton.textContent = `Saved ${link.download} to your downloads. Move it to public/narration/ and reload.`;
   451	      });
   452	      document.addEventListener("keydown", (event) => {
   453	        if (!tapping || !tapButton.isConnected) return;
   454	        if (event.code === "Space" && starts.length < sentences.length) starts.push(audio.currentTime);
   455	        else if (event.code === "Backspace") starts.pop();
   456	        else return;
   457	        event.preventDefault();
   458	        show();
   459	      });
   460	    }
   461	  });
   462	</script>

