   287	        seek.value = String(audio.currentTime);
   288	        seek.style.setProperty("--fill", `${total ? (audio.currentTime / total) * 100 : 0}%`);
   289	        time.textContent = total ? `${clock(audio.currentTime)} / ${clock(total)}` : clock(audio.currentTime);
