   294	        q("[data-icon-muted]").classList.toggle("hidden", !audio.muted);
   295	        mute.setAttribute("aria-label", audio.muted ? "Unmute" : "Mute");
   296	        rate.textContent = `${audio.playbackRate}x`;
   297	      };
