   299	      const listen = document.querySelector<HTMLButtonElement>("[data-listen]")!;
   300	      const open = (show: boolean) => {
   301	        player.hidden = !show;
   302	        listen.hidden = show;
   303	      };
   304	      audio.controls = false;
   305	      audio.hidden = true;
   306	      open(false);
   307	      listen.addEventListener("click", () => {
   308	        open(true);
   309	        audio.play();
   310	        play.focus();
   311	      });
