   413	    // Dev only: play the recording and press Space as each sentence starts.
   414	    // Saving downloads <slug>.vtt, which goes in public/narration/.
   415	    const tapButton = import.meta.env.DEV ? document.querySelector<HTMLButtonElement>("button[data-tap]") : null;
   416	    if (tapButton) {
   417	      const TAP_LAG = 0.2; // seconds a tap trails the voice; tune if highlights feel late or early
