   419	      let tapping = false;
   420	      const stamp = (t: number) => new Date(Math.max(t, 0) * 1000).toISOString().slice(11, 23);
   421	      const show = () => {
   422	        const current = sentences[starts.length - 1];
   423	        if (current) {
   424	          CSS.highlights.set("narration", new Highlight(current.range));
   425	          current.range.startContainer.parentElement?.scrollIntoView({ block: "center" });
   426	        } else CSS.highlights.delete("narration");
