   428	      };
   429	      tapButton.addEventListener("click", () => {
   430	        tapButton.blur(); // so Space doesn't re-click the button
   431	        if (!tapping) {
   432	          tapping = true;
   433	          track.mode = "disabled"; // old timings must not fight the taps
   434	          starts.length = 0;
   435	          audio.currentTime = 0;
   436	          audio.play();
   437	          show();
   438	          return;
   439	        }
   440	        tapping = false;
   441	        audio.pause();
   442	        const cues = starts.map((start, i) => {
   443	          const text = sentences[i].range.toString().replace(/\s+/g, " ").trim().replace(/&/g, "&amp;").replace(/</g, "&lt;");
