---
import Close from "../Icons/Close.astro";
import Minus from "../Icons/Minus.astro";
import Pause from "../Icons/Pause.astro";
import Play from "../Icons/Play.astro";
import Plus from "../Icons/Plus.astro";
import SkipBack from "../Icons/SkipBack.astro";
import SkipForward from "../Icons/SkipForward.astro";
import Volume from "../Icons/Volume.astro";
import VolumeMuted from "../Icons/VolumeMuted.astro";
import AudioVersionSwitch from "./AudioVersionSwitch.astro";
import TimingRecorder from "./TimingRecorder.astro";
import { narrationSrc } from "../../consts";

interface Props {
  slug: string;
  originalAudio: boolean;
}

const { slug, originalAudio } = Astro.props;
const src = narrationSrc(slug);
---

<!-- Not sticky on phones, where the full player would cover a third of the screen. -->
<div class="z-10 sm:sticky sm:top-2">
  <!-- Native controls until the script swaps in the custom player, so it still plays without JS. -->
  <audio data-narration controls preload="metadata" src={src} class="mt-9 w-full">
    <track kind="metadata" src={`/narration/${slug}.vtt`} default />
  </audio>
  <div data-player hidden role="group" aria-label="Narration player" class="mt-7 flex flex-col gap-3.5 rounded-3xl border border-blue-1 bg-[#fffdf7] px-5 pt-4.5 pb-4 shadow-[0_1px_2px_rgba(26,26,26,0.04),0_10px_28px_-18px_rgba(26,26,26,0.35)]">
    <div class="flex items-center justify-between gap-2">
      <span class="truncate text-[15px]">Listen · read by Sara</span>
      <span class="flex shrink-0 items-center gap-1">
        <span data-time class="text-[13px] tabular-nums text-[#6b6860]">0:00</span>
        <button data-close type="button" aria-label="Close player" class="-mr-2 grid size-9 cursor-pointer place-items-center rounded-full text-[#4a4843] hover:bg-black-1/5">
          <Close size={18} />
        </button>
      </span>
    </div>
    <input data-seek type="range" min="0" max="0" step="0.1" value="0" aria-label="Seek" class="h-1 w-full cursor-pointer" />
    <div class="flex flex-wrap items-center justify-between gap-3">
      <div class="flex min-w-37 flex-1 items-center gap-2">
        <button data-mute type="button" aria-label="Mute" aria-pressed="false" class="group grid size-11 cursor-pointer place-items-center rounded-full text-[#4a4843] hover:bg-black-1/5">
          <Volume size={20} class="group-aria-pressed:hidden" />
          <VolumeMuted size={20} class="hidden group-aria-pressed:block" />
        </button>
        {originalAudio && <AudioVersionSwitch src={src} />}
      </div>
      <div class="flex items-center gap-3">
        <button data-skip="-10" type="button" aria-label="Back 10 seconds" class="relative grid size-11 cursor-pointer place-items-center rounded-full hover:bg-black-1/5">
          <SkipBack size={24} />
          <span aria-hidden="true" class="absolute pt-0.5 font-sans text-[9px] font-semibold">10</span>
        </button>
        <button data-play type="button" aria-label="Play narration" aria-pressed="false" class="group grid size-14 cursor-pointer place-items-center rounded-full bg-blue-1 text-white-1 transition hover:brightness-110 active:scale-95">
          <Play size={22} class="translate-x-px group-aria-pressed:hidden" />
          <Pause size={22} class="hidden group-aria-pressed:block" />
        </button>
        <button data-skip="10" type="button" aria-label="Forward 10 seconds" class="relative grid size-11 cursor-pointer place-items-center rounded-full hover:bg-black-1/5">
          <SkipForward size={24} />
          <span aria-hidden="true" class="absolute pt-0.5 font-sans text-[9px] font-semibold">10</span>
        </button>
      </div>
      <div class="flex min-w-37 flex-1 justify-end">
        <div role="group" aria-label="Playback speed" class="inline-flex items-center rounded-full border border-black-1/15">
          <button data-speed="-1" type="button" aria-label="Slower" class="grid size-10 cursor-pointer place-items-center rounded-full hover:bg-black-1/5">
            <Minus />
          </button>
          <!-- "x", not "×": the Recoleta demo font has no × glyph. -->
          <span data-rate aria-live="polite" class="min-w-11 text-center text-sm tabular-nums">1x</span>
          <button data-speed="1" type="button" aria-label="Faster" class="grid size-10 cursor-pointer place-items-center rounded-full hover:bg-black-1/5">
            <Plus />
          </button>
        </div>
      </div>
    </div>
  </div>
</div>
{import.meta.env.DEV && <TimingRecorder slug={slug} />}

<style>
  :global(::highlight(narration)) {
    background-color: color-mix(in srgb, var(--color-blue-1) 30%, transparent);
  }
  /* Thin scrubber, filled up to the playhead (--fill, set by the script). */
  [data-seek] {
    appearance: none;
    height: 4px;
    background: linear-gradient(to right, var(--color-blue-1) var(--fill, 0%), color-mix(in srgb, var(--color-black-1) 12%, transparent) 0);
    border-radius: 999px;
  }
  [data-seek]::-webkit-slider-thumb {
    appearance: none;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--color-blue-1);
  }
  [data-seek]::-moz-range-thumb {
    width: 12px;
    height: 12px;
    border: 0;
    border-radius: 50%;
    background: var(--color-blue-1);
  }
</style>

<script>
  import { norm, sentenceRanges } from "../../lib/narration";

  const speeds = [0.75, 1, 1.25, 1.5, 1.75, 2];
  const clock = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;

  document.addEventListener("astro:page-load", () => {
    CSS.highlights?.delete("narration");
    const audio = document.querySelector<HTMLAudioElement>("audio[data-narration]");
    const player = document.querySelector<HTMLElement>("[data-player]");
    const listen = document.querySelector<HTMLButtonElement>("[data-listen]");
    if (!audio || !player || !listen) return;

    const play = player.querySelector<HTMLButtonElement>("[data-play]")!;
    const mute = player.querySelector<HTMLButtonElement>("[data-mute]")!;
    const seek = player.querySelector<HTMLInputElement>("[data-seek]")!;
    const time = player.querySelector<HTMLElement>("[data-time]")!;
    const rate = player.querySelector<HTMLElement>("[data-rate]")!;

    const sync = () => {
      const total = Number.isFinite(audio.duration) ? audio.duration : 0;
      seek.max = String(total);
      seek.valueAsNumber = audio.currentTime;
      seek.style.setProperty("--fill", `${total && (audio.currentTime / total) * 100}%`);
      time.textContent = total ? `${clock(audio.currentTime)} / ${clock(total)}` : clock(audio.currentTime);
      play.ariaPressed = String(!audio.paused);
      mute.ariaPressed = String(audio.muted);
      rate.textContent = `${audio.playbackRate}x`;
    };
    for (const event of ["loadedmetadata", "timeupdate", "play", "pause", "volumechange", "ratechange"]) {
      audio.addEventListener(event, sync);
    }

    const open = (show: boolean) => {
      player.hidden = !show;
      listen.hidden = show;
    };
    audio.controls = false;
    audio.hidden = true;
    open(false);
    listen.addEventListener("click", () => {
      open(true);
      audio.play();
      play.focus();
    });

    seek.addEventListener("input", () => (audio.currentTime = seek.valueAsNumber));
    player.addEventListener("click", (event) => {
      const button = (event.target as Element).closest("button");
      if (!button) return;
      const { skip, speed } = button.dataset;
      if (button === play) audio.paused ? audio.play() : audio.pause();
      else if (button === mute) audio.muted = !audio.muted;
      else if (skip) audio.currentTime += Number(skip); // the browser clamps to 0..duration
      else if (speed) {
        const next = speeds[speeds.indexOf(audio.playbackRate) + Number(speed)];
        // Default too, so the speed survives a Krisp / Original switch.
        if (next) audio.playbackRate = audio.defaultPlaybackRate = next;
      } else if (button.hasAttribute("data-close")) {
        audio.pause();
        open(false);
        listen.focus();
      }
    });
    sync();

    // Highlights the sentence being read. Each .vtt cue is one sentence.
    const track = audio.textTracks[0];
    const article = document.querySelector("article[data-article]");
    if (!track || !article || !CSS.highlights) return;

    const sentences = sentenceRanges(article);
    // Cues match sentences by text, in order, so editing the article after
    // recording only un-highlights the edited sentence.
    let byCue: Map<TextTrackCue, Range> | undefined;
    const matchCues = () => {
      byCue = new Map();
      let from = 0;
      for (const cue of track.cues ?? []) {
        const key = norm((cue as VTTCue).getCueAsHTML().textContent ?? "");
        const i = sentences.findIndex((s, i) => i >= from && s.key === key);
        if (i < 0) continue;
        byCue.set(cue, sentences[i].range);
        from = i + 1;
      }
    };

    const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
    track.mode = "hidden"; // load cues and fire cuechange without rendering them
    track.addEventListener("cuechange", () => {
      byCue ??= (matchCues(), byCue);
      const cue = track.activeCues?.[0];
      const range = cue && byCue!.get(cue);
      if (!range) return;
      CSS.highlights.set("narration", new Highlight(range));
      if (!audio.paused) {
        range.startContainer.parentElement?.scrollIntoView({ block: "center", behavior: reducedMotion.matches ? "auto" : "smooth" });
      }
    });
  });
</script>

