---
interface Props {
  src: string;
}

const { src } = Astro.props;
const versions = [
  ["Krisp", src],
  ["Original", src.replace(/\.mp3$/, ".original.mp3")],
];
---

<div role="radiogroup" aria-label="Audio version" class="inline-flex rounded-full bg-black-1/6 p-0.75 text-[13px]">
  {
    versions.map(([label, url], i) => (
      <button data-version={url} type="button" role="radio" aria-checked={String(i === 0)} class="min-h-8 cursor-pointer rounded-full px-3 text-[#4a4843] aria-checked:bg-[#fffdf7] aria-checked:text-black-1 aria-checked:shadow-sm">
        {label}
      </button>
    ))
  }
</div>

<script>
  // Swaps the file under the player, keeping the position and play state.
  document.addEventListener("astro:page-load", () => {
    const audio = document.querySelector<HTMLAudioElement>("audio[data-narration]");
    const buttons = document.querySelectorAll<HTMLButtonElement>("[data-version]");
    for (const button of buttons) {
      button.addEventListener("click", () => {
        if (!audio || button.ariaChecked === "true") return;
        for (const other of buttons) other.ariaChecked = String(other === button);
        const { currentTime, paused } = audio;
        audio.src = button.dataset.version!;
        audio.addEventListener("loadedmetadata", () => {
          audio.currentTime = currentTime;
          if (!paused) audio.play();
        }, { once: true });
      });
    }
  });
</script>

